  const n=src.length,act=(aS+aS2)/(n*1.6),inh=(iS+iS2)/(n*1.6);
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.07+sy*0.05-t*0.6)*0.5+Math.sin(sx*0.02+sy*0.08+t*0.4)*0.5)/3+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
