  const cell2=Math.tanh((Math.cos(sx*0.12+1)*Math.cos(sy*0.13-0.5)+Math.sin((sx-sy)*0.08-t*0.7)*0.4)*1.2)*0.2;
  const flow=Math.sin(sx*0.05+Math.sin(sy*0.04+t)*2+t*0.5)*Math.cos(sy*0.06+Math.cos(sx*0.03-t)*1.5-t*0.3)*0.25;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+spiral2*0.4+cell+cell2+flow)*2.0);
  const micro=Math.sin(sx*0.3+t*3)*Math.sin(sy*0.35-t*2.5)*0.08;
